// Collects cleanup callbacks and runs them on close().
export class Scope {
  constructor() {
    this.callbacks = [];
    this.closed = false;
  }

  /** Register a cleanup callback (may be async). */
  defer(cb) {
    if (this.closed) throw new Error('scope already closed');
    this.callbacks.push(cb);
  }

  /**
   * Run deferred callbacks in LIFO order. Every callback runs even if an earlier
   * one throws. Rejects with the error if exactly one failed, or an AggregateError
   * (errors in throw order) if several failed. Calls after the first are no-ops.
   */
  async close() {
    if (this.closed) return;
    this.closed = true;
    const errors = [];
    while (this.callbacks.length > 0) {
      const cb = this.callbacks.pop();
      try {
        await cb();
      } catch (err) {
        errors.push(err);
      }
    }
    if (errors.length === 1) throw errors[0];
    if (errors.length > 1) {
      throw new AggregateError(errors, `${errors.length} scope callbacks failed`);
    }
  }
}
```

