```js
// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }
//
// Events are applied strictly in seq order starting at `startSeq`.
// Events that arrive early are buffered until every lower seq has been applied.
// Redelivered events (id already applied or buffered) and stale events
// (seq already applied) are ignored.

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this.nextSeq = startSeq;
    this.buffer = new Map();       // seq -> event, received but not yet applied
    this.bufferedIds = new Set();  // ids currently in buffer
    this.appliedIds = new Set();   // ids already applied
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this.buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    if (!Number.isInteger(event.seq)) {
      throw new TypeError(`event seq must be an integer, got ${event.seq}`);
    }
    const { id, seq } = event;

    // Stale: this seq has already been applied.
    if (seq < this.nextSeq) return [];

    // Duplicate delivery: already applied or already buffered.
    if (this.appliedIds.has(id) || this.bufferedIds.has(id)) return [];

    // Another event already occupies this seq in the buffer; keep the first.
    if (this.buffer.has(seq)) return [];

    // Early event: buffer until the gap before it is filled.
    if (seq > this.nextSeq) {
      this.buffer.set(seq, event);
      this.bufferedIds.add(id);
      return [];
    }

    // seq === nextSeq: apply it, then drain consecutive buffered events.
    // apply() runs before any state changes, so if it throws, the event is
    // not recorded as applied and a redelivery can retry it.
    const applied = [];
    this.apply(event);
    this.#commit(event, applied);

    for (let queued = this.buffer.get(this.nextSeq); queued; queued = this.buffer.get(this.nextSeq)) {
      this.apply(queued);
      this.buffer.delete(queued.seq);
      this.bufferedIds.delete(queued.id);
      this.#commit(queued, applied);
    }

    return applied;
  }

  #commit(event, applied) {
    this.appliedIds.add(event.id);
    this.lastSeq = event.seq;
    this.nextSeq += 1;
    applied.push(event);
  }
}
```

