    return applied;
  }

  /** Apply consecutive buffered events starting at nextSeq. */
  #drain(applied) {
    for (let queued = this.buffer.get(this.nextSeq); queued !== undefined; queued = this.buffer.get(this.nextSeq)) {
      this.#applyAndCommit(queued, applied);
      this.buffer.delete(queued.seq);
      this.bufferedIds.delete(queued.id);
    }
  }

  #applyAndCommit(event, applied) {
    this.apply(event);
    this.appliedIds.add(event.id);
    this.lastSeq = event.seq;
    this.nextSeq += 1;
    applied.push(event);
  }
}
